import assert from 'node:assert/strict';
const root=process.argv[2];
const outcomes=[];
async function check(name,fn){try{await fn();outcomes.push({name,pass:true});}catch(e){if(e.code!=='ERR_ASSERTION')throw e;outcomes.push({name,pass:false,actual:e.actual,expected:e.expected});}}

const logic=await import(root+'/logic.ts');const domain=await import(root+'/domain.ts');
await check('rank after removal has a gap',()=>assert.equal(logic.moveUp([{id:'a',position:1,status:'NEW'},{id:'b',position:2,status:'NEW'},{id:'d',position:4,status:'NEW'},{id:'e',position:5,status:'NEW'}],3).position,3));
await check('both half-open window bounds and held appointment',()=>{for(const origin of [1800000000000,2100000000000]){const events=[{at:origin-10,status:'HELD'},{at:origin+100,status:'PLANNED'},{at:origin+50,status:'CANCELLED'}];for(const [offset,expected] of [[-1,false],[0,true],[99,true],[100,false],[101,false]])assert.equal(logic.fitsWindow(origin+Number(offset),{sentAt:origin},events,origin),expected);}});
await check('started then postponed and done agree with domain',()=>{for(const [stop,expected] of [[{id:'p',position:1,status:'POSTPONED',startedOn:'2025-01-01'},true],[{id:'d',position:2,status:'DONE',startedOn:'2025-01-01'},false],[{id:'n',position:3,status:'NEW'},false]]){assert.equal(logic.screenRequiresReason(stop),expected);assert.equal(domain.requiresReason(stop),expected);}});
await check('real mounted form loses A upload when owner becomes B',async()=>{const {JSDOM}=await import(root+'/node_modules/jsdom/lib/api.js');const window=new JSDOM('<div id="root"></div>',{url:'http://localhost'}).window;Object.assign(globalThis,{window,document:window.document,HTMLElement:window.HTMLElement,IS_REACT_ACT_ENVIRONMENT:true});const React=(await import(root+'/node_modules/react/index.js')).default;const {act}=React;const {createRoot}=await import(root+'/node_modules/react-dom/client.js');const {PlanningScreen}=await import(root+'/PlanningScreen.tsx');let submitted;const ui=createRoot(document.getElementById('root'));const onSubmit=x=>submitted=x;await act(async()=>ui.render(React.createElement(PlanningScreen,{storeId:'A',proposal:{title:'A order',fileId:'file-A'},onSubmit})));await act(async()=>document.querySelector('button').click());assert.equal(document.querySelector('input').value,'A order');await act(async()=>ui.render(React.createElement(PlanningScreen,{storeId:'B',onSubmit})));await act(async()=>document.querySelector('form').dispatchEvent(new window.Event('submit',{bubbles:true,cancelable:true})));assert.notEqual(submitted.fileId,'file-A');assert.notEqual(submitted.title,'A order');await act(async()=>ui.unmount());window.close();});
